import{_t as e,it as t,n,rt as r}from"./chunks/framework.Dp2H9twy.js";var i=JSON.parse(`{"title":"Standards Scope","description":"","frontmatter":{"packageVersion":"0.1.0"},"headers":[],"relativePath":"reference/standards.md","filePath":"site/versions/v0.1.0/reference/standards.md","lastUpdated":0}`),a={name:`reference/standards.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="standards-scope" tabindex="-1">Standards Scope <a class="header-anchor" href="#standards-scope" aria-label="Permalink to “Standards Scope”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>RFC 5280 path validation</td><td>partial</td><td>Core path validation, name constraints, policy processing, malformed-DER coverage, PKITS conformance subset</td></tr><tr><td>RFC 6960 OCSP</td><td>partial</td><td>Request/response parsing, signature checks, responder authorization, nonce/freshness</td></tr><tr><td>RFC 6125 service identity</td><td>partial</td><td>DNS-ID, IP-ID, URI-ID, SRV-ID, wildcard, IDNA, opt-in CN-compat</td></tr><tr><td>RFC 9618 policy validation</td><td>partial</td><td>Policy state, enforcement, outputs, focused PKITS coverage</td></tr></tbody></table><h2 id="what-ships" tabindex="-1">What ships <a class="header-anchor" href="#what-ships" aria-label="Permalink to “What ships”">​</a></h2><h3 id="rfc-5280-path-validation" tabindex="-1">RFC 5280 path validation <a class="header-anchor" href="#rfc-5280-path-validation" aria-label="Permalink to “RFC 5280 path validation”">​</a></h3><ul><li>DER parsing strict enough to reject malformed certificates</li><li>Issuer/subject chaining across candidate paths</li><li>Signature verification using the evolving working public key</li><li>Validity time checks (<code>notBefore</code> / <code>notAfter</code>)</li><li><code>basicConstraints</code> enforcement for CA certificates</li><li><code>pathLenConstraint</code> enforcement</li><li><code>keyUsage</code> enforcement (<code>keyCertSign</code> for CAs)</li><li>Self-issued vs non-self-issued processing</li><li>Supported-form name constraints (DNS, URI, email, IP)</li><li>Critical extension rejection for unrecognized OIDs</li></ul><h3 id="rfc-6960-ocsp" tabindex="-1">RFC 6960 OCSP <a class="header-anchor" href="#rfc-6960-ocsp" aria-label="Permalink to “RFC 6960 OCSP”">​</a></h3><ul><li>Request creation with CertID (issuer hash + serial)</li><li>Response parsing with status, certs, timestamps</li><li>Signature verification</li><li>Responder authorization (CA-signed, delegated with <code>ocspSigning</code> EKU)</li><li>Nonce matching</li><li>Freshness checks</li></ul><h3 id="crl-processing" tabindex="-1">CRL processing <a class="header-anchor" href="#crl-processing" aria-label="Permalink to “CRL processing”">​</a></h3><ul><li>Delta CRL merge</li><li>Indirect issuer handling</li><li>Scope matching</li><li>Basic CRL parsing and revocation checks</li></ul><h3 id="rfc-6125-service-identity" tabindex="-1">RFC 6125 service identity <a class="header-anchor" href="#rfc-6125-service-identity" aria-label="Permalink to “RFC 6125 service identity”">​</a></h3><ul><li>DNS-ID with single-level wildcard matching</li><li>IP-ID with IPv6 normalization</li><li>URI-ID scheme + host matching</li><li>SRV-ID via otherName SAN</li><li>IDNA-aware comparison</li><li>Opt-in CN compatibility (disabled by default)</li></ul><h3 id="rfc-9618-policy-validation" tabindex="-1">RFC 9618 policy validation <a class="header-anchor" href="#rfc-9618-policy-validation" aria-label="Permalink to “RFC 9618 policy validation”">​</a></h3><ul><li>Policy state tracking across candidate paths</li><li>Explicit policy enforcement</li><li>Initial policy set validation</li></ul><h2 id="what-doesn-t-ship" tabindex="-1">What doesn&#39;t ship <a class="header-anchor" href="#what-doesn-t-ship" aria-label="Permalink to “What doesn&#39;t ship”">​</a></h2><ul><li>Full CRL distribution point processing</li><li>OCSP local responder-policy acceptance</li><li>Broader PKITS conformance (ongoing)</li><li>Full name constraint processing for all GeneralName forms</li></ul><p>For the authoritative scope boundary, see <a href="./../docs/PKIX-SCOPE"><code>PKIX-SCOPE.md</code></a>.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};